const LOGIN_HTML=`
<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
*{margin:0;padding:0;box-sizing:border-box;font-family:-apple-system,"PingFang SC","Microsoft YaHei",sans-serif}
body{background:linear-gradient(160deg,#EEF3FB,#E3EAF6);min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px;color:#1F2733}
.card{width:100%;max-width:380px;background:#fff;border-radius:18px;padding:34px 30px;box-shadow:0 18px 50px rgba(40,60,100,.14)}
.logo{width:52px;height:52px;border-radius:15px;background:linear-gradient(135deg,#3B82F6,#22D3EE);display:grid;place-items:center;margin:0 auto 14px;color:#fff;font-weight:800;font-size:20px;letter-spacing:1px}
h1{text-align:center;font-size:21px;margin-bottom:4px}
.sub{text-align:center;color:#8A93A6;font-size:13px;margin-bottom:26px}
.field{margin-bottom:16px;position:relative}
.field label{display:block;font-size:12.5px;color:#5B6678;margin-bottom:7px;font-weight:500}
.input-wrap{display:flex;align-items:center;border:1.5px solid #DCE2EC;border-radius:11px;transition:.18s;background:#FAFBFD}
.input-wrap:focus-within{border-color:#3B82F6;box-shadow:0 0 0 3px rgba(59,130,246,.12);background:#fff}
.prefix{padding:0 10px 0 14px;color:#5B6678;font-size:14px;border-right:1px solid #E4E9F2;height:22px;display:flex;align-items:center}
.input-wrap input{flex:1;border:none;outline:none;background:transparent;padding:13px 12px;font-size:14.5px;width:100%;color:#1F2733}
.sms-btn{flex:none;margin-right:6px;padding:8px 12px;border-radius:8px;background:#EFF5FF;color:#2563EB;font-size:12.5px;font-weight:500;border:none;white-space:nowrap;transition:.15s}
.sms-btn:disabled{background:#F1F3F7;color:#9AA3B5;cursor:not-allowed}
.agree{display:flex;align-items:flex-start;gap:8px;font-size:12px;color:#8A93A6;margin:4px 0 20px;line-height:1.6}
.agree input{margin-top:2px;accent-color:#3B82F6;width:15px;height:15px}
.agree a{color:#2563EB;text-decoration:none}
.login-btn{width:100%;padding:14px;border-radius:11px;border:none;font-size:15px;font-weight:600;background:#D6DDE8;color:#8C96A8;transition:.2s;cursor:not-allowed}
.login-btn.ready{background:linear-gradient(135deg,#3B82F6,#2563EB);color:#fff;cursor:pointer;box-shadow:0 8px 20px rgba(37,99,235,.32)}
.login-btn.ready:active{transform:scale(.98)}
.alt{display:flex;justify-content:space-between;margin-top:18px;font-size:12.5px}
.alt a{color:#5B6678;text-decoration:none}
.alt a:hover{color:#2563EB}
.err{color:#E5484D;font-size:11.5px;margin-top:6px;display:none}
.err.show{display:block}
.toast{position:fixed;left:50%;bottom:40px;transform:translateX(-50%) translateY(20px);background:#1F2733;color:#fff;padding:11px 22px;border-radius:10px;font-size:13px;opacity:0;transition:.25s;pointer-events:none}
.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}
</style></head><body>
<div class="card">
  <div class="logo">NX</div>
  <h1>欢迎回来</h1>
  <div class="sub">未注册的手机号验证后将自动创建账号</div>
  <div class="field">
    <label>手机号</label>
    <div class="input-wrap"><span class="prefix">+86</span><input id="phone" inputmode="numeric" maxlength="11" placeholder="请输入 11 位手机号"></div>
    <div class="err" id="phoneErr">请输入正确的 11 位手机号</div>
  </div>
  <div class="field">
    <label>短信验证码</label>
    <div class="input-wrap"><input id="sms" inputmode="numeric" maxlength="6" placeholder="6 位验证码">
      <button class="sms-btn" id="smsBtn">获取验证码</button>
    </div>
    <div class="err" id="smsErr">请输入 6 位数字验证码</div>
  </div>
  <label class="agree"><input type="checkbox" id="agree"><span>我已阅读并同意 <a href="javascript:void(0)">《用户服务协议》</a> 与 <a href="javascript:void(0)">《隐私政策》</a></span></label>
  <button class="login-btn" id="loginBtn" disabled>登录 / 注册</button>
  <div class="alt"><a href="javascript:void(0)">密码登录</a><a href="javascript:void(0)">登录遇到问题？</a></div>
</div>
<div class="toast" id="t">登录成功，正在进入…</div>

var phone=document.getElementById('phone'),sms=document.getElementById('sms'),agree=document.getElementById('agree'),
btn=document.getElementById('loginBtn'),smsBtn=document.getElementById('smsBtn'),t=document.getElementById('t'),cd=0,timer;
function refresh(){var ok=/^1[3-9]\\d{9}$/.test(phone.value)&&sms.value.length===6&&agree.checked;btn.disabled=!ok;btn.className='login-btn'+(ok?' ready':'');}
[phone,sms,agree].forEach(function(el){el.addEventListener('input',refresh);el.addEventListener('change',refresh);});
phone.addEventListener('input',function(){phone.value=phone.value.replace(/\\D/g,'');document.getElementById('phoneErr').classList.remove('show');});
sms.addEventListener('input',function(){sms.value=sms.value.replace(/\\D/g,'');});
smsBtn.addEventListener('click',function(){
  if(!/^1[3-9]\\d{9}$/.test(phone.value)){document.getElementById('phoneErr').classList.add('show');return;}
  cd=60;smsBtn.disabled=true;timer=setInterval(function(){cd--;smsBtn.textContent=cd+'s 后重发';if(cd<=0){clearInterval(timer);smsBtn.disabled=false;smsBtn.textContent='获取验证码';}},1000);
  showToast('验证码已发送（演示码 123456）');
});
btn.addEventListener('click',function(){if(btn.disabled)return;showToast('登录成功，正在进入…');});
function showToast(m){t.textContent=m;t.classList.add('show');setTimeout(function(){t.classList.remove('show');},1800);}
<\/script>
</body></html>`;

