var stMap={'正常':'ok','冻结':'fz','已注销':'off'};
function render(list){
 document.getElementById('tbody').innerHTML=list.map(function(d){
  return '<tr><td><input type="checkbox" class="rowck" data-id="'+d.id+'"></td>'+
  '<td><span class="avatar" style="background:'+d.c+'">'+d.name.slice(0,1)+'</span><span><span class="u-name">'+d.name+'</span><div class="u-id">'+d.id+'</div></span></td>'+
  '<td>'+d.ph+'</td><td>'+d.role+'</td><td><span class="tag-st '+stMap[d.st]+'">'+d.st+'</span></td>'+
  '<td>'+d.reg+'</td><td>'+d.act+'</td>'+
  '<td class="op" style="text-align:right"><a href="javascript:void(0)">详情</a><a href="javascript:void(0)">编辑</a><a href="javascript:void(0)" class="danger">冻结</a></td></tr>';
 }).join('');
 bindRow();
}
function bindRow(){document.querySelectorAll('.rowck').forEach(function(c){c.addEventListener('change',refreshBatch);});}
function refreshBatch(){
 var n=document.querySelectorAll('.rowck:checked').length;
 document.getElementById('batchBar').classList.toggle('show',n>0);
 document.getElementById('selNum').textContent=n;
}
render(DATA);
var timer;
document.getElementById('kw').addEventListener('input',function(e){
 clearTimeout(timer);var v=e.target.value;
 timer=setTimeout(function(){render(DATA.filter(function(d){return (d.name+d.ph+d.id).indexOf(v)>=0;}));},300);
});
document.getElementById('stSel').addEventListener('change',function(e){
 var v=e.target.value;render(v?DATA.filter(function(d){return d.st===v;}):DATA);
});
document.getElementById('checkAll').addEventListener('change',function(e){
 document.querySelectorAll('.rowck').forEach(function(c){c.checked=e.target.checked;});refreshBatch();
});
document.getElementById('batchClear').addEventListener('click',function(){
 document.querySelectorAll('.rowck').forEach(function(c){c.checked=false;});document.getElementById('checkAll').checked=false;refreshBatch();
});
