        products: [
          { icon:'fa-ring', name:'Cartier 戒指 18K', spec:'18K玫瑰金', qty:1, price:12000, store:'三亚国际免税城', group:'香化一组（68680401）', guide:'林小婷', refund:'none', attrRule:'r15last' },
          { icon:'fa-clock', name:'欧米茄星座女表', spec:'27mm', qty:1, price:8000, store:'三亚国际免税城', group:'香化一组（68680401）', guide:'王小丽', refund:'none', attrRule:'r15last' }
        ],
